import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceArea, Label } from 'recharts';
import { Users, Pill, Activity, ArrowLeft, AlertCircle, Calendar, ChevronDown, Search, X, Database, AlertTriangle, HeartPulse, Shuffle, Building2, Loader2, ClipboardCheck, Printer, Copy, ShieldCheck, ChevronLeft } from 'lucide-react';
import './index.css';

const API_BASE = "http://127.0.0.1:5000/api";

const categories = ["Cardiovascular", "Dermatologic", "Endocrine & metabolic", "Gastrointestinal", "Genitourinary", "Hematologic & oncologic", "Hepatic", "Local", "Nervous system", "Neuromuscular & skeletal", "Respiratory", "Otic", "Renal", "Hypersensitivity", "Immunologic", "Psychiatric", "Musculoskeletal", "Ophthalmic", "Miscellaneous"];

export default function App() {
  const [view, setView] = useState('overview'); 
  const [patients, setPatients] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [admissions, setAdmissions] = useState([]);
  const [currentAdm, setCurrentAdm] = useState(null);
  const [clinicalData, setClinicalData] = useState(null);

  const [windowSize, setWindowSize] = useState(7);
  const [startIndex, setStartIndex] = useState(0);
  const [isAdmMenuOpen, setIsAdmMenuOpen] = useState(false);

  // 藥物查詢狀態
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [stats, setStats] = useState({ total: 0, with_reactions: 0 });
  const [showCategories, setShowCategories] = useState(false);
  const [selectedDrug, setSelectedDrug] = useState(null);

  // 1. 初始化：載入病人名單與藥物統計
  useEffect(() => {
    fetch(`${API_BASE}/patients`).then(res => res.json()).then(setPatients).catch(() => alert("後端未啟動！"));
    fetch(`${API_BASE}/stats`).then(res => res.json()).then(setStats).catch(() => {});
  }, []);

  // 2. 當選擇病人時，抓取該病人的住院紀錄
  const handleSelectPatient = (p) => {
    setSelectedPatient(p);
    fetch(`${API_BASE}/patients/${p.id}/admissions`)
      .then(res => res.json())
      .then(data => {
        setAdmissions(data);
        if(data.length > 0) handleSelectAdmission(data[0]);
        setView('dashboard');
      });
  };

  // 3. 當選擇特定住院紀錄時，抓取趨勢圖與用藥資料
  const handleSelectAdmission = (adm) => {
    setCurrentAdm(adm);
    setIsAdmMenuOpen(false);
    setClinicalData(null); // 清空舊資料
    fetch(`${API_BASE}/admissions/${adm.id}/details`)
      .then(res => res.json())
      .then(data => {
        setClinicalData(data);
        setStartIndex(0);
      });
  };

  const performSearch = async (params) => {
    setIsLoading(true);
    try {
      const q = new URLSearchParams(params).toString();
      const res = await fetch(`${API_BASE}/search?${q}`);
      const json = await res.json();
      setSearchResults(json.data || []);
    } finally { setIsLoading(false); }
  };

  // 智慧格式化函數 (略，同前版內容)
  const formatText = (text) => {
    if (!text || String(text).toLowerCase() === 'nan') return '無資料';
    return `<div class="text-lg leading-relaxed text-slate-700">${text}</div>`;
  };

  const renderSidebar = () => (
    <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm print:hidden">
      <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic"><Activity /> ADR PRO</div>
      <button onClick={() => setView('overview')} className={"flex items-center gap-3 p-4 rounded-2xl font-bold mb-4 " + (view === 'overview' || view === 'dashboard' ? "bg-blue-600 text-white" : "text-slate-400")}>
        <Users size={18} /> 患者住院紀錄
      </button>
      <button onClick={() => setView('repository')} className={"flex items-center gap-3 p-4 rounded-2xl font-bold " + (view === 'repository' || view === 'drug_detail' ? "bg-blue-600 text-white" : "text-slate-400")}>
        <Pill size={18} /> 藥物查詢
      </button>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans print:block print:h-auto">
      <style>{`@media print { html, body, #root { height: auto !important; overflow: visible !important; display: block !important; } .print:hidden { display: none !important; } }`}</style>
      {renderSidebar()}

      {/* 首頁：患者住院紀錄 */}
      {view === 'overview' && (
        <div className="flex-1 p-12 overflow-y-auto">
          <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase">患者住院紀錄</h1>
          <div className="bg-white rounded-2xl shadow-sm border overflow-hidden max-w-5xl">
            <table className="w-full text-left font-bold">
              <thead className="bg-slate-50 text-slate-400 text-xs uppercase"><tr><th className="p-6">ID</th><th className="p-6">病患</th><th className="p-6">Na / K</th><th className="p-6">狀態</th></tr></thead>
              <tbody className="divide-y">
                {patients.map(p => (
                  <tr key={p.id} onClick={() => handleSelectPatient(p)} className="hover:bg-blue-50 cursor-pointer transition-all">
                    <td className="p-6 text-blue-600">{p.id}</td>
                    <td className="p-6 text-slate-700">{p.name} {p.info}</td>
                    <td className="p-6 text-slate-500">{p.na} / {p.k}</td>
                    <td className="p-6"><span className="bg-rose-100 text-rose-600 px-4 py-1.5 rounded-full text-xs">{p.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 臨床圖表頁面 */}
      {view === 'dashboard' && clinicalData && (
        <div className="flex-1 p-8 overflow-y-auto print:hidden">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4 relative">
              <button onClick={() => setView('overview')} className="p-3 bg-white border rounded-xl shadow-sm"><ArrowLeft size={18} /></button>
              <button onClick={() => setIsAdmMenuOpen(!isAdmMenuOpen)} className="bg-white px-6 py-3 rounded-2xl border flex items-center gap-3 font-bold text-slate-700 shadow-sm transition-all hover:bg-slate-50">
                <Calendar size={16} className="text-blue-500"/> {currentAdm?.date} <ChevronDown size={14} />
              </button>
              {isAdmMenuOpen && (
                <div className="absolute top-14 left-14 mt-2 w-72 bg-white border rounded-2xl shadow-xl z-50 overflow-hidden">
                  {admissions.map(adm => (
                    <div key={adm.id} onClick={() => handleSelectAdmission(adm)} className="px-6 py-4 hover:bg-blue-50 cursor-pointer font-bold border-b last:border-b-0 text-slate-600">
                      {adm.date}
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="flex gap-2">
              {[3, 7, 14].map(d => (
                <button key={d} onClick={() => { setWindowSize(d); setStartIndex(0); }} className={windowSize === d ? "px-6 py-2 rounded-lg bg-blue-600 text-white font-bold" : "px-6 py-2 bg-white text-slate-400 border"}>{d}D</button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] p-10 border shadow-sm mb-8">
            <div className="h-72 w-full mb-6">
              <ResponsiveContainer>
                <LineChart data={clinicalData.trends.slice(startIndex, startIndex + windowSize)}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                  <XAxis dataKey="date" />
                  <YAxis yAxisId="na" domain={[120, 160]} orientation="left" />
                  <YAxis yAxisId="k" domain={[2, 8]} orientation="right" />
                  <Tooltip />
                  <ReferenceArea yAxisId="na" y1={135} y2={145} fill="#F97316" fillOpacity={0.05} />
                  <Line yAxisId="na" type="monotone" dataKey="na" stroke="#F97316" strokeWidth={4} isAnimationActive={false} />
                  <Line yAxisId="k" type="monotone" dataKey="k" stroke="#6366F1" strokeWidth={4} isAnimationActive={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>
            <input type="range" min="0" max={Math.max(0, clinicalData.trends.length - windowSize)} value={startIndex} onChange={(e) => setStartIndex(parseInt(e.target.value))} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600" />

            <div className="space-y-4 pt-10 border-t mt-10">
              {clinicalData.gantt.map((med, i) => {
                const left = Math.max(0, ((med.startIdx - startIndex) / windowSize) * 100);
                const width = Math.max(0, ((med.endIdx - med.startIdx) / windowSize) * 100);
                return (
                  <div key={i} className="flex items-center">
                    <div className="w-48 text-left font-bold text-slate-700">{med.name}</div>
                    <div className="flex-1 h-8 bg-slate-50 rounded-xl relative overflow-hidden border">
                      {width > 0 && <div className="absolute h-full opacity-80" style={{ left: left + '%', width: width + '%', backgroundColor: med.color }}></div>}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="bg-white rounded-3xl p-10 border shadow-sm mb-8 text-left">
             <h2 className="font-black text-slate-700 mb-6 border-l-4 border-blue-600 pl-4 uppercase tracking-tight">實際用藥全紀錄與 ADR 分析</h2>
             <table className="w-full text-sm">
                <thead className="text-slate-400 border-b text-left"><tr><th className="pb-4">藥物</th><th className="pb-4">開始時間</th><th className="pb-4">劑量變動</th><th className="pb-4 text-right">狀態</th></tr></thead>
                <tbody className="divide-y">
                  {clinicalData.logs.map((log, i) => (
                    <tr key={i}><td className="py-4 font-bold text-slate-700">{log.name}</td><td className="py-4 font-mono text-slate-500">{log.start}</td><td className="py-4 text-slate-600">{log.dose.join(' / ')}</td><td className="py-4 text-right font-bold text-emerald-500">{log.status}</td></tr>
                  ))}
                </tbody>
             </table>
          </div>
        </div>
      )}

      {/* 藥物查詢與詳情頁面 (省略渲染部分，邏輯維持不變) */}
      {view === 'repository' && (
        <div className="flex-1 p-12 overflow-y-auto bg-slate-50">
          <div className="max-w-4xl mx-auto text-center">
            <h1 className="text-4xl font-black text-[#0f4c81] mb-8 flex items-center justify-center gap-3"><Building2 size={40}/> 台北榮總藥物查詢</h1>
            <div className="relative mb-8">
              <Search className="absolute left-6 top-5 text-slate-300"/>
              <input value={searchQuery} onChange={(e)=>setSearchQuery(e.target.value)} onKeyDown={(e)=>e.key==='Enter'&&performSearch({keyword:searchQuery})} className="w-full p-5 pl-16 rounded-full border shadow-xl text-xl outline-none" placeholder="搜尋藥名或代碼..."/>
            </div>
            {/* ... 統計按鈕與結果表格 ... */}
            <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
                <table className="w-full text-left">
                   <tbody className="divide-y">
                     {searchResults.map((d,i)=>(
                       <tr key={i} onClick={()=>{setSelectedDrug(d); setView('drug_detail')}} className="hover:bg-blue-50 cursor-pointer">
                         <td className="p-5 font-mono text-slate-500">{d.drug_id || d.id}</td>
                         <td className="p-5 font-bold text-slate-700">{d.name}</td>
                         <td className="p-5 text-right"><span className="bg-rose-50 text-rose-500 px-3 py-1 rounded-full text-xs font-bold">查看詳情</span></td>
                       </tr>
                     ))}
                   </tbody>
                </table>
            </div>
          </div>
        </div>
      )}

      {view === 'drug_detail' && selectedDrug && (
        <div className="flex-1 bg-white print:block print:h-auto overflow-y-auto">
          <div className="p-8 max-w-5xl mx-auto print:p-0">
            <div className="flex justify-between items-center mb-8 border-b pb-6 print:hidden">
              <button onClick={() => setView('repository')} className="flex items-center gap-2 px-4 py-2 bg-slate-100 rounded-full font-bold"><ChevronLeft size={18}/> 返回</button>
              <h1 className="text-3xl font-black text-[#0f4c81]">{selectedDrug.name}</h1>
              <button onClick={() => window.print()} className="p-3 bg-blue-600 text-white rounded-full"><Printer size={20}/></button>
            </div>
            <div dangerouslySetInnerHTML={{ __html: formatText(selectedDrug.adverse_reaction) }} />
          </div>
        </div>
      )}
    </div>
  );
}
